function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}function tag(t,c='blue'){return `<span class="tag ${c}">${esc(t)}</span>`}function btn(t,a,c='',extra=''){return `<button class="btn ${c}" data-action="${a}" ${extra}>${esc(t)}</button>`}function head(t,p,a=''){return `<div class="pagehead"><div><h1>${esc(t)}</h1><p>${esc(p)}</p></div><div class="headactions">${a}</div></div>`}function kpi(v,l,t='',c='blue'){return `<div class="card kpi">${t?tag(t,c):''}<strong>${esc(v)}</strong><small>${esc(l)}</small></div>`}function table(h,r){return `<div class="tablewrap"><table><thead><tr>${h.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${r.map(x=>`<tr>${x.map(y=>`<td>${y}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}function taskCard(t){return `<div class="task"><div class="taskicon ${t.priority==='High'?'red':t.priority==='Medium'?'amber':'blue'}">${esc(t.type[0])}</div><div class="grow"><b>${esc(t.title)}</b><p>${esc(t.detail)}</p><p><strong>${esc(t.from)}</strong> · ${esc(t.type)} · Due ${esc(t.due)}</p></div><button class="btn" data-action="${t.action}" data-id="${t.id}" data-person="${t.person||''}" data-fixture="${t.fixture||''}">Open</button></div>`}function progress(v){return `<div class="progress"><i style="width:${Math.max(0,Math.min(100,v))}%"></i></div>`}function statusTag(s){const c=/Paid|Ready|Complete|Confirmed|Acknowledged|Active|Resolved|Approved/.test(s)?'green':/High|Missing|No umpires|Open - follow-up|Needs rostering/.test(s)?'red':/Review|Pending|Awaiting|Changed|In progress|Coach needed|Needs response/.test(s)?'amber':'blue';return tag(s,c)}
function allowed(id){return (access[role]||[]).includes(id)}function canAction(a){return !actionAccess[a]||actionAccess[a].includes(role)}
function buildNav(){const n=document.getElementById('nav');n.innerHTML='';sections.forEach(([label,ids])=>{const h=document.createElement('div');h.className='navlabel';h.textContent=label;n.appendChild(h);const box=document.createElement('div');box.className='nav';ids.filter(allowed).forEach(id=>{const b=document.createElement('button');b.dataset.go=id;b.textContent=pages[id];b.className=id===page?'active':'';box.appendChild(b)});n.appendChild(box)});document.getElementById('role').innerHTML=Object.entries(roles).map(([k,v])=>`<option value="${k}" ${k===role?'selected':''}>${v}</option>`).join('')}
function dashboard(){const open=tasks.filter(t=>t.status==='Open').length,gaps=fixtures.filter(f=>f.status!=='Ready').length,out=payments.filter(p=>p.status!=='Paid').reduce((s,p)=>s+p.amount,0);return head('Saturday control centre','Operational overview across fixtures, availability, rostering, compliance, communications and finance.',btn('Open Tasks','tasks','primary')+btn('Open Roster','roster')+btn('Open Finance','finance'))+`<div class="grid kpis">${kpi(fixtures.length,'Games in demo round','Round 8')}${kpi(gaps,'Games needing action','Rostering','red')}${kpi(open,'Open Tasks','Action inbox','amber')}${kpi('$'+out,'Outstanding payments','Umpires + coaches','green')}</div><div class="grid two" style="margin-top:12px"><div class="card"><h2>Round readiness</h2><p class="sub">Coverage and confirmations are calculated from dummy operational data.</p><p>Umpire coverage ${progress(78)}</p><p>Coach coverage ${progress(75)}</p><p>Availability confirmations ${progress(83)}</p><p>Appointment confirmations ${progress(72)}</p></div><div class="card"><h2>Priority Tasks</h2>${tasks.filter(t=>t.status==='Open').slice(0,4).map(taskCard).join('')}</div></div><div class="card" style="margin-top:12px"><h2>Operating flow</h2><div class="flow">${['fixtures','availability','roster','tasks','gameday','payments','finance'].map((id,i)=>`${i?'<span class="arrow">→</span>':''}<div class="node click ${id==='tasks'?'blue':''}" data-go="${id}">${pages[id]}</div>`).join('')}</div></div>`}
function fixturesPage(){const rows=fixtures.filter(f=>state.fixtureFilter==='all'||f.status!=='Ready');return head('Fixtures','Full dummy fixture register with coverage, coaching obligations, confirmations and click-through detail.',btn('Season Import','import')+btn('Add dummy game','addFixture','primary'))+`<div class="grid kpis">${kpi(fixtures.length,'Games loaded')}${kpi(fixtures.filter(f=>f.status==='Ready').length,'Roster ready','Covered','green')}${kpi(fixtures.filter(f=>!f.ump1||!f.ump2).length,'Missing umpire coverage','Action','red')}${kpi(fixtures.filter(f=>!f.coach&&/Development|C Badge/.test(f.coachReason)).length,'Coach gaps','Development','amber')}</div><div class="card" style="margin-top:12px"><div class="toolbar"><button class="btn ${state.fixtureFilter==='all'?'primary':''}" data-action="fixtureAll">All games</button><button class="btn ${state.fixtureFilter==='action'?'primary':''}" data-action="fixtureAction">Needs action</button></div>${table(['ID','Date','Time','Court','Grade','Game','Umpire 1','Umpire 2','Coach','Confirmed','Status','Action'],rows.map(f=>[esc(f.id),esc(f.date),esc(f.time),esc(f.court),esc(f.grade),esc(f.game),f.ump1?esc(f.ump1):tag('Missing','red'),f.ump2?esc(f.ump2):tag('Missing','red'),f.coach?esc(f.coach):tag('Missing','red'),`${f.confirmed}/3`,statusTag(f.status),`<button class="btn" data-action="fixtureDetail" data-fixture="${f.id}">Open</button>`]))}</div>`}
function umpiresPage(){const openInc=people.reduce((s,p)=>s+p.incidents.filter(i=>/Open/.test(i[6])).length,0),out=people.reduce((s,p)=>s+p.payments.filter(x=>x[4]!=='Paid').reduce((z,x)=>z+x[3],0),0);return head('Umpire register','Open every umpire or coach to review registrations, development comments, communications, conflicts, restricted incidents, payments and audit history.',btn('Add person','addPerson','primary'))+`<div class="grid kpis">${kpi(people.length,'Registered people')}${kpi(people.filter(p=>p.age<18).length,'Junior umpires','Guardian linked','blue')}${kpi(openInc,'Open compliance matters','Restricted','red')}${kpi('$'+out,'Outstanding payments')}</div><div class="card" style="margin-top:12px">${table(['Name','Role','Age','Development','Registration','Conflict flag','Outstanding','Action'],people.map(p=>[esc(p.name),esc(p.role),esc(p.age),esc(p.level),tag('Active','green'),esc(p.conflicts),`$${p.payments.filter(x=>x[4]!=='Paid').reduce((s,x)=>s+x[3],0)}`,`<button class="btn" data-action="openUmpire" data-person="${p.id}">Open profile</button>`]))}</div>`}
function availabilityPage(){return head('Availability','Working availability register for umpires and coaches. Changes create a roster-review Task.',btn('Send availability reminder','availabilityReminder')+btn('Submit request','newRequest','primary'))+`<div class="grid kpis">${kpi(availability.length,'People')}${kpi(availability.filter(a=>a.status==='Confirmed').length,'Confirmed','Round 8','green')}${kpi(availability.filter(a=>a.status==='Changed').length,'Changed','Review roster','amber')}${kpi(availability.filter(a=>a.status==='Pending').length,'Pending','Needs response','red')}</div><div class="card" style="margin-top:12px">${table(['Person','Role','Age','Saturday','Sunday','Preference','Status','Action'],availability.map((a,i)=>[esc(a.name),esc(a.role),esc(a.age),esc(a.sat),esc(a.sun),esc(a.pref),statusTag(a.status),`<button class="btn" data-action="editAvailability" data-id="${i}">Edit</button>`]))}</div>`}
function rosterPage(){return head('Roster Board','Assign umpires and coaches together. Missing positions create Tasks and AutoRoster can fill eligible dummy candidates.',btn('AutoRoster','autoRoster','primary')+btn(state.published?'Published':'Publish roster','publish'))+`<div class="grid kpis">${kpi(fixtures.reduce((s,f)=>s+(f.ump1?1:0)+(f.ump2?1:0),0),'Umpire positions filled')}${kpi(fixtures.filter(f=>f.coach&&f.coach!=='Not required').length,'Coach positions filled')}${kpi(fixtures.filter(f=>!f.ump1||!f.ump2||(!f.coach&&/Development|target/.test(f.coachReason))).length,'Open roster gaps','Tasks','red')}${kpi(state.published?'Yes':'No','Roster published',state.published?'Live':'Draft',state.published?'green':'amber')}</div><div class="card" style="margin-top:12px"><div class="board"><div></div><div class="court">Court 1</div><div class="court">Court 2</div><div class="court">Court 3</div><div class="time">8:00</div>${fixtures.slice(0,3).map(gameCard).join('')}<div class="time">9:20+</div>${fixtures.slice(3,6).map(gameCard).join('')}</div></div>`}function gameCard(f){return `<div class="game"><b>${esc(f.grade)}</b><small>${esc(f.game)}</small><div class="official ${!f.ump1?'empty':''}">${f.ump1?esc(f.ump1):'Umpire 1 missing'}</div><div class="official ${!f.ump2?'empty':''}">${f.ump2?esc(f.ump2):'Umpire 2 missing'}</div><div class="coach ${!f.coach?'empty':''}">${f.coach?esc(f.coach):'Coach missing'}<br><small>${esc(f.coachReason)}</small></div><button class="btn" data-action="fixtureDetail" data-fixture="${f.id}">Manage</button></div>`}
function tasksPage(){const open=tasks.filter(t=>t.status==='Open'&&(state.taskFilter==='all'||t.type===state.taskFilter));return head('Tasks','One operational inbox for rostering, coaching, confirmations, communications, compliance and finance.',btn('Create request','newRequest','primary'))+`<div class="grid kpis">${kpi(tasks.filter(t=>t.status==='Open').length,'Open')}${kpi(tasks.filter(t=>t.status==='Open'&&t.type==='Rostering').length,'Rostering')}${kpi(tasks.filter(t=>t.status==='Open'&&t.type==='Compliance').length,'Compliance','Restricted','red')}${kpi(tasks.filter(t=>t.status==='Open'&&/Communication|Confirmation/.test(t.type)).length,'Communications')}</div><div class="card" style="margin-top:12px"><div class="toolbar"><select id="taskFilter" data-action="taskFilter"><option value="all">All Tasks</option>${[...new Set(tasks.map(t=>t.type))].map(x=>`<option ${state.taskFilter===x?'selected':''}>${x}</option>`).join('')}</select></div>${open.map(taskCard).join('')||'<div class="success">No open Tasks in this filter.</div>'}</div>`}
function gameDayPage(){return head('Game Day','Court-centric check-in, late arrivals, no-shows, coach attendance and emergency replacement.',btn('Print court pack','printPack')+btn('Open Tasks','tasks','primary'))+`<div class="grid kpis">${kpi(fixtures.filter(f=>f.checkedIn>=2).length,'Games checked in')}${kpi(fixtures.reduce((s,f)=>s+f.checkedIn,0),'People checked in')}${kpi(fixtures.filter(f=>!f.ump1||!f.ump2).length,'Coverage risks','Before first whistle','red')}${kpi(fixtures.filter(f=>!f.coach&&f.coachReason!=='No coaching rule').length,'Coach risks','Development','amber')}</div><div class="card" style="margin-top:12px">${table(['Time','Court','Game','Umpire 1','Umpire 2','Coach','Check-in','Action'],fixtures.map(f=>[esc(f.time),esc(f.court),esc(f.grade),f.ump1?esc(f.ump1):tag('Missing','red'),f.ump2?esc(f.ump2):tag('Missing','red'),f.coach?esc(f.coach):tag('Missing','red'),`${f.checkedIn}/${[f.ump1,f.ump2,f.coach].filter(x=>x&&x!=='Not required').length}`,`<button class="btn" data-action="gameCheckin" data-fixture="${f.id}">Check in / manage</button>`]))}</div>`}
function financePage(){const included=payments.filter(p=>!p.status.includes('Review')),total=included.reduce((s,p)=>s+p.amount,0),hold=payments.filter(p=>p.status.includes('Review')).reduce((s,p)=>s+p.amount,0),ready=batch.approval1&&batch.approval2;return head('Finance','Payment operations for umpires and coaches with two-person approval, export control and full audit trail.',btn('Match fee ledger','payments'))+`<div class="grid kpis">${kpi('$'+total,'Batch total')}${kpi('$'+hold,'On hold / review','Exception','amber')}${kpi(batch.approval1?'1':'0','Approval 1')}${kpi(batch.approval2?'1':'0','Approval 2')}</div><div class="grid two" style="margin-top:12px"><div class="card"><h2>Batch ${batch.id}</h2>${table(['Person','Role','Games','Amount','Status'],payments.map(p=>[esc(p.person),esc(p.role),esc(p.games),`$${p.amount}`,statusTag(p.status)]))}</div><div class="card"><h2>Approval & export</h2><p>${batch.approval1?tag('Approval 1: '+batch.approval1,'green'):tag('Approval 1 required','amber')}</p><p>${batch.approval2?tag('Approval 2: '+batch.approval2,'green'):tag('Approval 2 required','amber')}</p>${btn('Approve as Finance Manager','approve1','primary')} ${btn('Approve as Partner','approve2')}<hr style="border:0;border-top:1px solid var(--line);margin:14px 0"><button class="btn ${ready?'primary':''}" data-action="downloadBank" ${ready?'':'disabled'}>Download bank CSV</button> <button class="btn" data-action="downloadXero" ${ready?'':'disabled'}>Download Xero CSV</button>${ready?'<br><br>'+btn('Mark batch paid','markPaid'):''}<div class="notice" style="margin-top:10px">Demo export formats only. Production bank and Xero mappings must be confirmed before real payments.</div></div></div><div class="card" style="margin-top:12px"><h2>Finance audit trail</h2>${timeline(auditEvents.filter(e=>e[1]==='Finance'))}</div>`}
function paymentsPage(){const total=payments.reduce((s,p)=>s+p.amount,0),hold=payments.filter(p=>p.status.includes('Review')).reduce((s,p)=>s+p.amount,0);return head('Match Fees','Detailed entitlement ledger feeding Finance. Review attendance and fee calculations before payment approval.',btn('Open Finance','finance','primary'))+`<div class="grid kpis">${kpi('$'+total,'Accrued')}${kpi(payments.filter(p=>!p.status.includes('Review')).length,'Ready for approval')}${kpi('$'+hold,'On hold','Attendance review','amber')}${kpi(payments.filter(p=>p.role==='Umpire Coach').length,'Coach fee lines')}</div><div class="card" style="margin-top:12px">${table(['Payment','Date','Person','Role','Game','Qty','Rate','Amount','Status','Action'],payments.map(p=>[esc(p.id),esc(p.date),esc(p.person),esc(p.role),esc(p.game),esc(p.games),`$${p.rate}`,`$${p.amount}`,statusTag(p.status),`<button class="btn" data-action="reviewFee" data-id="${p.id}">Review</button>`]))}</div>`}
function reportsPage(){const coached=people.filter(p=>/Bib|Badge/.test(p.level)).length,open=tasks.filter(t=>t.status==='Open').length;return head('Reports','Operational and season intelligence with drill-down-ready dummy measures.',btn('Export report CSV','exportReport','primary'))+`<div class="toolbar"><select id="reportPeriod" data-action="reportPeriod"><option>Round 8</option><option>Season to date</option><option>Last 4 rounds</option></select></div><div class="grid kpis">${kpi('78%','Umpire coverage')}${kpi('75%','Coach coverage')}${kpi(open,'Open Tasks')}${kpi('$'+payments.reduce((s,p)=>s+p.amount,0),'Current fees')}</div><div class="grid three" style="margin-top:12px"><div class="card"><h3>Development</h3><p class="sub">Umpires with configured development levels: ${coached}</p><p>Green Bib ${progress(92)}</p><p>Blue Bib ${progress(79)}</p><p>C Badge ${progress(83)}</p></div><div class="card"><h3>Fairness</h3>${table(['Official','Games','Premier','Junior'],[['Ella J','8','0','8'],['Ruby S','10','0','10'],['Mia P','12','2','10'],['Helen A','9','3','6']])}</div><div class="card"><h3>Compliance</h3><p>${tag('1 open safeguarding matter','red')}</p><p>${tag('0 expired registrations','green')}</p><p>${tag('1 unresolved availability confirmation','amber')}</p></div></div>`}
function notificationsPage(){const rows=notifications.filter(n=>state.notificationFilter==='all'||n.status===state.notificationFilter);return head('Notifications','Audit-friendly push, SMS and email communications for appointments, changes, reminders and requests.',btn('New broadcast','broadcast','primary'))+`<div class="grid kpis">${kpi(notifications.length,'Messages')}${kpi(notifications.filter(n=>n.status==='Acknowledged').length,'Acknowledged','Confirmed','green')}${kpi(notifications.filter(n=>/Awaiting|Needs/.test(n.status)).length,'Need response','Task candidates','amber')}${kpi(notifications.filter(n=>n.status==='Draft').length,'Draft')}</div><div class="card" style="margin-top:12px"><div class="toolbar"><select data-action="notificationFilter"><option value="all">All messages</option><option>Acknowledged</option><option>Awaiting response</option><option>Needs response</option><option>Draft</option></select></div>${table(['Channel','Audience','Subject','Sent','Status','Action'],rows.map(n=>[esc(n.channel),esc(n.audience),esc(n.subject),esc(n.time),statusTag(n.status),`<button class="btn" data-action="notificationDetail" data-id="${n.id}">Open</button>`]))}</div>`}
function importPage(){const labels=['Upload','Map columns','Validate','Preview changes','Confirm'];const warnings=[['Missing venue alias','Pizzey Park Main → Pizzey Park','2 rows'],['Duplicate Game ID','GC-260622','1 row'],['Court double booking','22 Aug 10:40 Court 3','1 conflict']];return head('Season Import','Settings workflow for full-season CSV/Excel imports with saved mappings, validation, change detection and upsert behaviour.',btn('Load dummy season file','loadImport','primary'))+`<div class="grid kpis">${kpi(state.imported?'186':'0','Games detected')}${kpi(state.imported?'14':'0','Rounds')}${kpi(state.imported?'4':'0','Validation warnings','Review','amber')}${kpi(state.imported?'2':'0','Existing-game changes')}</div><div class="card" style="margin-top:12px"><h2>Import workflow</h2><div class="flow">${labels.map((x,i)=>`${i?'<span class="arrow">→</span>':''}<div class="node ${state.importStage===i+1?'blue':''}">${i+1}. ${x}</div>`).join('')}</div><br>${state.imported?table(['Validation','Example','Count'],warnings.map(w=>w.map(esc))):'<div class="notice">Load the dummy file to simulate automatic column detection and validation.</div>'}<div style="margin-top:12px">${state.imported&&state.importStage<5?btn('Next step','importNext','primary'):''}${state.imported&&state.importStage===5?btn('Confirm import','saveImport','primary'):''}</div></div><div class="card" style="margin-top:12px"><h2>Saved source mappings</h2>${table(['Source','Mapping','Game ID','Last used'],[['Gold Coast Netball','GCNA Season v1','Game ID','15 Aug 2026'],['Queensland Rep','Qld Rep v2','Fixture ID','11 Aug 2026']])}</div>`}
function rulesPage(){return head('Rules & Supply','Admin-configurable supply, conflict, break and game-requirement rules used by roster generation.',btn('Add rule','addRule','primary'))+`<div class="grid kpis">${kpi(supplyRules.length,'Active rule definitions')}${kpi('2','Umpires / standard game')}${kpi('1','Coach / development game')}${kpi('20 min','Minimum break rule')}</div><div class="card" style="margin-top:12px">${table(['Rule','Applies to','Outcome','Status','Action'],supplyRules.map(r=>[esc(r.name),esc(r.match),esc(r.rule),r.active?tag('Active','green'):tag('Inactive','amber'),`<button class="btn" data-action="editRule" data-id="${r.id}">Edit</button>`]))}</div><div class="grid two" style="margin-top:12px"><div class="card"><h3>Hard constraints</h3><p class="sub">Availability · overlap · accreditation · prohibited conflicts · max games · junior supervision.</p></div><div class="card"><h3>Soft constraints</h3><p class="sub">Fairness · preferred times · minimise gaps · mentor pairing · continuity · minimum changes after publish.</p></div></div>`}
function coachingPage(){const demand=people.filter(p=>/Bib|Badge/.test(p.level)).map(p=>{const lvl=levels.find(l=>l.name===p.level);return [p.name,p.level,lvl?lvl.coverage+'%':'10%',p.coachComments.length,p.coachComments.length?tag('Evidence recorded','green'):tag('Needs session','amber'),`<button class="btn" data-action="coachComment" data-person="${p.id}">Add comment</button>`]});return head('Coaching & Development','Configure level types and required coaching percentages, then track delivery and coach feedback by umpire.',btn('Add level type','addLevel','primary'))+`<div class="grid kpis">${kpi(levels.length,'Development levels')}${kpi('100%','Green Bib target')}${kpi('25%','C Badge target')}${kpi(fixtures.filter(f=>f.coach&&f.coach!=='Not required').length,'Coach assignments this round')}</div><div class="card" style="margin-top:12px"><h2>Level administration</h2>${table(['Level','Type','Coaching %','Method','Required coach','Action'],levels.map(l=>[esc(l.name),esc(l.type),tag(l.coverage+'%',l.coverage===100?'red':l.coverage>=50?'amber':'blue'),esc(l.method),esc(l.coach),`<button class="btn" data-action="editLevel" data-id="${l.id}">Edit</button>`]))}</div><div class="card" style="margin-top:12px"><h2>Development delivery</h2>${table(['Umpire','Level','Target','Coach comments','Status','Action'],demand)}</div>`}
function rolesPage(){return head('Roles & Access','Admin permissions model showing which user types can see and change each part of the system.',btn('Add custom role','addRole','primary'))+`<div class="grid kpis">${kpi(Object.keys(roles).length,'System roles')}${kpi('4','Admin / coordinator roles')}${kpi('3','Self-service roles')}${kpi('1','Read-only audit role')}</div><div class="card" style="margin-top:12px">${table(['Role','Access scope','Key controls','Preview'],permissionRows.map(r=>[esc(r[0]),esc(r[1]),esc(r[2]),`<button class="btn" data-action="previewRole" data-role="${Object.keys(roles).find(k=>roles[k]===r[0])||'clubAdmin'}">Preview</button>`]))}</div>`}
function juniorPage(){const juniors=people.filter(p=>p.age<18);return head('Junior & Guardian','Age-aware junior experience with guardian linkage, safeguarding visibility, appointment acknowledgement and escalation.',btn('Guardian message','guardianMessage','primary'))+`<div class="grid kpis">${kpi(juniors.length,'Junior officials')}${kpi(juniors.filter(p=>/linked/i.test(p.guardian)).length,'Guardians linked','Safeguarding','green')}${kpi(juniors.reduce((s,p)=>s+p.incidents.filter(i=>/Open/.test(i[6])).length,0),'Open restricted matters','Follow-up','red')}${kpi('9:00pm','Concept junior end-time rule')}</div><div class="card" style="margin-top:12px">${table(['Junior','Age','Level','Guardian','Next game','Conflict / note','Action'],juniors.map(p=>[esc(p.name),esc(p.age),esc(p.level),esc(p.guardian),esc(fixtures.find(f=>f.ump1===p.name||f.ump2===p.name)?.grade||'No assignment'),esc(p.conflicts),`<button class="btn" data-action="guardianAck" data-person="${p.id}">Acknowledge</button>`]))}</div><div class="notice" style="margin-top:12px">Restricted incident details are not exposed in the junior self-service view; authorised safeguarding roles manage them in the Umpire Register.</div>`}
function mobilePage(){const my=fixtures.filter(f=>f.ump1==='Ella J'||f.ump2==='Ella J');return head('Mobile Experience','Concept self-service experience for appointments, availability, directions, requests and accessibility.',btn('Submit request','newRequest','primary')+btn('Toggle large text','large'))+`<div class="grid three"><div class="card"><h3>My next appointment</h3>${my.length?`<b>${esc(my[0].time)} · Court ${esc(my[0].court)}</b><p class="sub">${esc(my[0].grade)} · ${esc(my[0].game)}</p>${tag('Confirmed','green')}`:'<p>No assignment.</p>'}</div><div class="card"><h3>My availability</h3><b>Saturday 8:00-12:00</b><p class="sub">Early games preferred</p>${btn('Change','editAvailability','','data-id="0"')}</div><div class="card"><h3>Help & safety</h3><p class="sub">Contact coordinator, report a concern or ask where to meet your coach.</p>${btn('Ask for help','newRequest')}</div></div><div class="card" style="margin-top:12px"><h3>My schedule</h3>${table(['Time','Court','Game','Coach','Status'],my.map(f=>[esc(f.time),esc(f.court),esc(f.grade),esc(f.coach||'None'),tag('Confirmed','green')]))}</div>`}
function auditPage(){const rows=auditEvents.filter(e=>state.auditFilter==='all'||e[1]===state.auditFilter);return head('Audit Trail','Immutable-concept history for roster changes, communications, compliance access and finance activity.',btn('Export audit CSV','exportAudit','primary'))+`<div class="grid kpis">${kpi(auditEvents.length,'Audit events')}${kpi(auditEvents.filter(e=>e[1]==='Compliance').length,'Compliance events')}${kpi(auditEvents.filter(e=>e[1]==='Finance').length,'Finance events')}${kpi(auditEvents.filter(e=>e[1]==='Communication').length,'Communication events')}</div><div class="card" style="margin-top:12px"><div class="toolbar"><select data-action="auditFilter"><option value="all">All event types</option>${[...new Set(auditEvents.map(e=>e[1]))].map(x=>`<option>${x}</option>`).join('')}</select></div>${table(['Date/time','Area','Event','Detail'],rows.map(r=>r.map(esc)))}</div>`}
function blueprintPage(){return head('Software Blueprint','Production architecture and domain model behind the concept, preserving the same scheduling engine for officials, coaches and future workforce roles.')+`<div class="card"><h2>Core domain</h2><div class="flow">${['Organisation','Season','Fixture','Requirement','Assignment','Person','Timesheet / Fee','Payment'].map((x,i)=>`${i?'<span class="arrow">→</span>':''}<div class="node">${x}</div>`).join('')}</div></div><div class="grid three" style="margin-top:12px"><div class="card"><h3>Scheduling service</h3><p class="sub">Hard constraints, soft scoring, candidate explanations, minimum-change repair and fairness.</p></div><div class="card"><h3>Operational services</h3><p class="sub">Tasks, notifications, check-in, incidents, coaching delivery, audit and reporting.</p></div><div class="card"><h3>Finance services</h3><p class="sub">Fee engine, approvals, batch control, bank export, Xero mapping and reconciliation.</p></div></div><div class="card" style="margin-top:12px"><h2>Concept API</h2>${table(['Method','Endpoint','Purpose'],[['POST','/fixtures','Import/upsert fixtures'],['POST','/rosters/generate','Run AutoRoster'],['POST','/assignments','Create/change umpire or coach assignment'],['POST','/availability','Update availability'],['POST','/incidents','Record restricted compliance matter'],['POST','/payment-batches/approve','Record independent approval'],['GET','/tasks','Operational work queue']])}</div>`}
function playbookPage(){return head('Playbook','Start-of-season and weekly operating checklist for the Pizzey Park pilot.',btn('Reset demo checklist','resetPlaybook'))+`<div class="grid kpis">${kpi(playbookItems.filter(x=>x[1]==='Complete').length,'Complete')}${kpi(playbookItems.filter(x=>x[1]==='In progress').length,'In progress')}${kpi(playbookItems.filter(x=>x[1]==='Not started').length,'Not started')}${kpi(playbookItems.length,'Total steps')}</div><div class="card" style="margin-top:12px">${playbookItems.map((x,i)=>`<div class="checkrow"><input type="checkbox" data-action="playbookToggle" data-id="${i}" ${x[1]==='Complete'?'checked':''}><div><b>${esc(x[0])}</b><p class="sub">Owner: ${esc(x[2])} · ${esc(x[1])}</p></div></div>`).join('')}</div>`}
function actionPlanPage(){const complete=actionPlan.filter(x=>x.status==='Complete').length;return head('Action Plan','Concept completion plan with measurable gates before production software build.',btn('Export plan CSV','exportPlan','primary'))+`<div class="grid kpis">${kpi(actionPlan.length,'Actions')}${kpi(complete,'Complete')}${kpi(actionPlan.filter(x=>x.status==='In progress').length,'In progress')}${kpi(Math.round(complete/actionPlan.length*100)+'%','Overall completion')}</div><div class="card" style="margin-top:12px">${table(['Phase','Action','Status','Action'],actionPlan.map(x=>[tag(x.phase,x.phase==='P0'?'green':x.phase==='P1'?'blue':x.phase==='P2'?'amber':'purple'),esc(x.item),statusTag(x.status),`<button class="btn" data-action="planToggle" data-id="${x.id}">${x.status==='Complete'?'Reopen':'Mark complete'}</button>`]))}</div><div class="card" style="margin-top:12px"><h3>Concept exit gate</h3><p class="sub">Import a season → identify club umpire obligations → collect availability → AutoRoster umpires and coaches → resolve Tasks → publish → manage game day → capture compliance matters → calculate fees → dual approve → export bank/Xero files.</p></div>`}
function timeline(rows){return `<div class="timeline">${rows.map(e=>`<div class="event"><b>${esc(e[0])} · ${esc(e[2])}</b><p>${esc(e[3]||e[1])}</p></div>`).join('')}</div>`}
function profileHTML(p){const paid=p.payments.filter(x=>x[4]==='Paid').reduce((s,x)=>s+x[3],0),out=p.payments.filter(x=>x[4]!=='Paid').reduce((s,x)=>s+x[3],0),openInc=p.incidents.filter(i=>/Open/.test(i[6])).length;return `<div class="profile"><div class="profileAside"><strong>${esc(p.name)}</strong><p class="sub">${esc(p.role)} · Age ${p.age}</p>${tag(p.level,'blue')}<p><b>Guardian</b><br><span class="sub">${esc(p.guardian)}</span></p><p><b>Availability</b><br><span class="sub">${esc(p.availability)}</span></p><p><b>Conflict flags</b><br><span class="sub">${esc(p.conflicts)}</span></p><p>${openInc?tag(openInc+' open compliance matter','red'):tag('No open compliance matters','green')}</p></div><div><div class="tabs">${['summary','registrations','coaching','communications','incidents','payments','audit'].map(t=>`<button class="${profileTab===t?'active':''}" data-action="profileTab" data-tab="${t}" data-person="${p.id}">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div>${profileTabContent(p,paid,out)}</div></div>`}
function profileTabContent(p,paid,out){if(profileTab==='summary')return `<div class="grid three">${kpi(p.registrations.length,'Registrations')}${kpi(p.coachComments.length,'Coach comments')}${kpi(p.incidents.length,'Recorded matters')}</div><div class="card" style="margin-top:12px"><h3>Current summary</h3><p class="sub">Registration active · ${esc(p.availability)} · ${esc(p.conflicts)}.</p></div>`;if(profileTab==='registrations')return table(['Year','Registration / accreditation','Status','Expiry'],p.registrations.map(r=>r.map(esc)));if(profileTab==='coaching')return `${btn('Add coach comment','coachComment','primary',`data-person="${p.id}"`)}<br><br>${p.coachComments.length?timeline(p.coachComments.map(c=>[c[0],c[1],c[1],c[2]+' · '+c[3]])):'<p class="sub">No coach comments recorded.</p>'}`;if(profileTab==='communications')return table(['Date/time','From / to','Communication','Status'],p.communications.map(r=>r.map(esc)));if(profileTab==='incidents')return `${btn('Record new incident / issue','newIncident','primary',`data-person="${p.id}"`)}<br><br>${p.incidents.length?table(['Date','Category','Game / court','Description','Immediate action','Owner','Status'],p.incidents.map(r=>r.map(esc))):'<p class="sub">No incidents recorded.</p>'}<div class="notice" style="margin-top:10px">Sensitive safeguarding, abuse, behavioural and complaint records are restricted compliance records.</div>`;if(profileTab==='payments')return `<div class="grid two">${kpi('$'+paid,'Paid')}${kpi('$'+out,'Outstanding')}</div><div style="margin-top:12px">${table(['Date','Round','Role','Amount','Status'],p.payments.map(x=>[esc(x[0]),esc(x[1]),esc(x[2]),'$'+x[3],statusTag(x[4])]))}</div>`;return timeline([['15 Aug 6:10pm','Profile','Communication received','Guardian message recorded'],['10 Aug 3:45pm','Compliance','Incident recorded','Restricted incident record created'],['8 Aug 5:20pm','Finance','Payment marked paid','Round 7 payment completed']])}
const PAGE_RENDERERS={dashboard,fixtures:fixturesPage,umpires:umpiresPage,availability:availabilityPage,roster:rosterPage,tasks:tasksPage,gameday:gameDayPage,finance:financePage,payments:paymentsPage,reports:reportsPage,notifications:notificationsPage,import:importPage,rules:rulesPage,coaching:coachingPage,roles:rolesPage,junior:juniorPage,mobile:mobilePage,audit:auditPage,blueprint:blueprintPage,playbook:playbookPage,actionplan:actionPlanPage};
function render(){document.getElementById('content').innerHTML=PAGE_RENDERERS[page]();document.getElementById('pageCrumb').textContent=pages[page];buildNav()}
